//! Stress lookup: an embedded RUAccent-derived dictionary plus the Python
//! frontend's rule fallback. Port of `training/voca_ru/text/stress.py`.
//!
//! The dictionary is generated by `scripts/gen/build_stress_dict.py` (top
//! forms by corpus frequency, sorted `word<TAB>stressed`, `+` before the
//! stressed vowel). It is embedded, not loaded from disk: no Python, no ONNX,
//! no network at runtime.

use std::collections::HashMap;
use std::sync::OnceLock;

use fancy_regex::{Captures, Regex};

use crate::symbols::STRESS;

pub const VOWEL_LETTERS: &str = "аеёиоуыэюя";

/// Monosyllabic function words are unstressed clitics; forcing a mark would
/// teach the wrong prosody. Same list as the Python frontend.
const CLITICS: [&str; 36] = [
    "в",
    "во",
    "на",
    "до",
    "от",
    "из",
    "к",
    "ко",
    "по",
    "с",
    "со",
    "у",
    "о",
    "об",
    "обо",
    "за",
    "под",
    "над",
    "при",
    "для",
    "без",
    "через",
    "между",
    "а",
    "и",
    "но",
    "или",
    "не",
    "ни",
    "же",
    "ли",
    "бы",
    "что",
    "ведь",
    "вот",
    "да",
];

/// The dictionary's dominant reading is wrong for years; hard override.
const CONTEXT_OVERRIDES: [(&str, &str); 2] = [("году", "год+у"), ("года", "г+ода")];

/// (suffix, vowels back from the last vowel).
const FALLBACK_SUFFIXES: [(&str, i32); 17] = [
    ("изация", 2),
    ("фикация", 2),
    ("ация", 2),
    ("ование", 2),
    ("ение", 2),
    ("ание", 2),
    ("ический", 2),
    ("ическая", 2),
    ("ическое", 2),
    ("ировать", 2),
    ("овать", 0),
    ("евать", 0),
    ("ативный", 1),
    ("ография", 2),
    ("ология", 2),
    ("изм", 0),
    ("ист", 0),
];

static DICT_TEXT: &[u8] = include_bytes!("data/stress_dict.txt");

fn dict() -> &'static HashMap<&'static str, &'static str> {
    static DICT: OnceLock<HashMap<&'static str, &'static str>> = OnceLock::new();
    DICT.get_or_init(|| {
        let text = std::str::from_utf8(DICT_TEXT).expect("stress dictionary is UTF-8");
        let mut map = HashMap::with_capacity(text.lines().count());
        for line in text.lines() {
            if let Some((word, marked)) = line.split_once('\t') {
                map.insert(word, marked);
            }
        }
        map
    })
}

fn word_re() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"[а-яё]+(?:-[а-яё]+)*").unwrap())
}

fn marked_word_re() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"[а-яё\u{0301}]+(?:-[а-яё\u{0301}]+)*").unwrap())
}

/// Remove combining acutes.
pub fn strip_stress(text: &str) -> String {
    text.replace(STRESS, "")
}

fn is_vowel_letter(c: char) -> bool {
    VOWEL_LETTERS.contains(c.to_lowercase().next().unwrap_or(c))
}

fn vowel_indices(word: &str) -> Vec<usize> {
    word.char_indices()
        .filter(|(_, c)| is_vowel_letter(*c))
        .map(|(i, _)| i)
        .collect()
}

/// Insert U+0301 after the `index`-th vowel letter of `word`.
pub fn mark_vowel(word: &str, index: usize) -> String {
    let mut seen: i32 = -1;
    for (pos, ch) in word.char_indices() {
        if is_vowel_letter(ch) {
            seen += 1;
            if seen as usize == index {
                let mut out = String::with_capacity(word.len() + 2);
                let end = pos + ch.len_utf8();
                out.push_str(&word[..end]);
                out.push(STRESS);
                out.push_str(&word[end..]);
                return out;
            }
        }
    }
    word.to_string()
}

/// RUAccent's `+` notation -> combining acute after the vowel.
pub fn plus_to_acute(text: &str) -> String {
    let mut out = String::with_capacity(text.len() + 1);
    let mut chars = text.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '+' {
            if let Some(&next) = chars.peek() {
                if is_vowel_letter(next) {
                    out.push(next);
                    out.push(STRESS);
                    chars.next();
                    continue;
                }
            }
            out.push('+');
        } else {
            out.push(c);
        }
    }
    out
}

/// Uncertain stress for a word no dictionary entry covered.
pub fn fallback_stress(word: &str) -> String {
    let indices = vowel_indices(word);
    if indices.is_empty() {
        return word.to_string();
    }
    for (i, ch) in word.char_indices() {
        if ch.to_lowercase().next() == Some('ё') {
            let end = i + ch.len_utf8();
            return format!("{}{}{}", &word[..end], STRESS, &word[end..]);
        }
    }
    let lower = word.to_lowercase();
    for (suffix, back) in FALLBACK_SUFFIXES {
        if lower.ends_with(suffix) {
            let idx = (indices.len() as i32 - 1 - back).max(0) as usize;
            return mark_vowel(word, idx);
        }
    }
    let idx = if indices.len() > 1 {
        indices.len() - 2
    } else {
        0
    };
    mark_vowel(word, idx)
}

fn is_clitic(word: &str) -> bool {
    CLITICS.contains(&word.to_lowercase().as_str())
}

fn context_override(word: &str) -> Option<&'static str> {
    CONTEXT_OVERRIDES
        .iter()
        .find(|(w, _)| *w == word)
        .map(|(_, marked)| *marked)
}

fn mark_part(word: &str) -> String {
    if let Some(marked) = context_override(word) {
        return plus_to_acute(marked);
    }
    if let Some(marked) = dict().get(word) {
        return plus_to_acute(marked);
    }
    fallback_stress(word)
}

fn mark_word(word: &str) -> String {
    if word.contains('-') {
        word.split('-').map(mark_part).collect::<Vec<_>>().join("-")
    } else {
        mark_part(word)
    }
}

fn ensure_one_mark(text: &str) -> String {
    marked_word_re()
        .replace_all(text, |caps: &Captures<'_>| {
            let word = caps.get(0).unwrap().as_str();
            if word.contains(STRESS) || word.contains('+') {
                return plus_to_acute(word);
            }
            if is_clitic(word) {
                return word.to_string();
            }
            fallback_stress(word)
        })
        .into_owned()
}

/// Lowercase normalised text -> (stressed text, oov flag).
pub fn stressed(text: &str) -> (String, bool) {
    let text = strip_stress(text);
    let mut oov = false;
    let marked = word_re()
        .replace_all(&text, |caps: &Captures<'_>| {
            let word = caps.get(0).unwrap().as_str();
            for part in word.split('-') {
                if part.chars().count() > 1
                    && !dict().contains_key(part)
                    && context_override(part).is_none()
                {
                    oov = true;
                }
            }
            if is_clitic(word) {
                word.to_string()
            } else {
                mark_word(word)
            }
        })
        .into_owned();
    (ensure_one_mark(&marked), oov)
}

/// Number of embedded dictionary entries.
pub fn dictionary_len() -> usize {
    dict().len()
}

pub fn dictionary_contains(word: &str) -> bool {
    dict().contains_key(word)
}

/// [(stressed word, vowel index of the acute)] for tests and reports.
pub fn words_with_marks(text: &str) -> Vec<(String, Option<usize>)> {
    marked_word_re()
        .find_iter(text)
        .flatten()
        .map(|m| {
            let word = m.as_str();
            let mut index = None;
            for (i, ch) in word.char_indices() {
                if ch == STRESS {
                    let before = &word[..i];
                    index = Some(
                        before
                            .chars()
                            .filter(|c| is_vowel_letter(*c))
                            .count()
                            .saturating_sub(1),
                    );
                    break;
                }
            }
            (strip_stress(word), index)
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn dictionary_is_embedded_and_sorted() {
        assert!(dictionary_len() > 10_000);
        let text = std::str::from_utf8(DICT_TEXT).unwrap();
        let mut previous = "";
        for line in text.lines().take(1000) {
            let (word, _) = line.split_once('\t').unwrap();
            assert!(
                previous.is_empty() || previous < word,
                "not sorted at {word}"
            );
            previous = word;
        }
    }

    #[test]
    fn plus_notation() {
        assert_eq!(plus_to_acute("год+у"), "году\u{0301}");
        assert_eq!(plus_to_acute("аар+оновец"), "ааро\u{0301}новец");
    }

    #[test]
    fn fallback_rules() {
        assert_eq!(fallback_stress("ёлка"), "ё\u{0301}лка");
        assert_eq!(fallback_stress("красота"), "красо\u{0301}та");
        assert_eq!(fallback_stress("машина"), "маши\u{0301}на");
    }

    #[test]
    fn clitics_stay_unmarked() {
        let (out, _) = stressed("я иду в дом");
        assert!(out.starts_with("я\u{0301}") || out.starts_with("я "));
        assert!(out.contains(" в "));
        assert!(!out.contains("в\u{0301}"));
    }
}
